// Builds src/hero3d/viewerHtml.generated.ts (+ heroModels.generated.ts) — the
// self-contained HTML page the app's WebView shows for a club's 3D hero.
//
//   node scripts/build-hero3d.mjs [path-to-website-project]
//
// The page = three.js + the WEBSITE's own model builders
// (components/themes/hero3d/models.ts) + hero3d-viewer/entry.ts, so the phone
// draws exactly the same objects as the club's website. The generated file is
// committed: you only re-run this when the website's 3D models change.
// It reads the website project (default ../saasssss-club-updated) and its
// node_modules (for `three`); nothing is downloaded.
import { build } from "esbuild";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const web = resolve(root, process.argv[2] ?? "../saasssss-club-updated");

const modelsTs = resolve(web, "components/themes/hero3d/models.ts");
const threeDir = resolve(web, "node_modules/three");
const classicGlb = resolve(web, "public/models/dumbbell.glb");
for (const p of [modelsTs, threeDir, classicGlb]) {
  if (!existsSync(p)) {
    console.error(`Missing ${p}\nPass the website project folder: node scripts/build-hero3d.mjs <path>`);
    process.exit(1);
  }
}

const result = await build({
  entryPoints: [resolve(root, "hero3d-viewer/entry.ts")],
  bundle: true,
  write: false,
  minify: true,
  format: "iife",
  target: "es2019", // old Android WebViews
  legalComments: "none",
  // One copy of three for both the viewer and the website's models.ts.
  alias: { three: threeDir, "@hero/models": modelsTs },
  define: { "process.env.NODE_ENV": '"production"' },
  logLevel: "warning",
});

const bundle = result.outputFiles[0].text.replace(/<\/script/gi, "<\\/script");
const classicB64 = readFileSync(classicGlb).toString("base64");

// The ids of the 3D objects the website offers, read from its single source of
// truth (lib/website-themes.ts) so the app can never accept an id the viewer
// cannot draw, nor miss one that was added on the website.
const themesSrc = readFileSync(resolve(web, "lib/website-themes.ts"), "utf8");
const idsBlock = /HERO_MODEL_IDS\s*=\s*\[([\s\S]*?)\]\s*as const/.exec(themesSrc);
const heroIds = idsBlock ? [...idsBlock[1].matchAll(/"([a-z0-9-]+)"/g)].map((m) => m[1]) : [];
if (heroIds.length < 5) {
  console.error("Could not read HERO_MODEL_IDS from lib/website-themes.ts");
  process.exit(1);
}

// The page needs no network at all: block every request except inline code and
// blob:/data: URLs (embedded textures of a glTF), so a malicious model file can
// never make the phone fetch a remote URL.
const csp =
  "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src blob: data:; connect-src blob: data:";

const html =
  `<!doctype html><html><head><meta charset="utf-8">` +
  `<meta http-equiv="Content-Security-Policy" content="${csp}">` +
  `<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">` +
  `<style>html,body{margin:0;height:100%;background:transparent;overflow:hidden}` +
  `canvas{display:block;width:100%;height:100%;touch-action:none}</style></head>` +
  `<body><canvas id="c"></canvas>` +
  `<script>window.__CLASSIC_B64__=${JSON.stringify(classicB64)};</script>` +
  `<script>${bundle}</script></body></html>`;

const header = `// GENERATED by scripts/build-hero3d.mjs — do not edit by hand.\n// Re-run \`npm run build:hero3d\` after the website's 3D models change.\n`;

// Tiny file, safe to import at startup (ThemeSync validates the server's choice with it).
writeFileSync(
  resolve(root, "src/hero3d/heroModels.generated.ts"),
  header +
    `/** 3D objects the viewer can draw (same list as the website). */\n` +
    `export const SUPPORTED_HERO_MODELS: readonly string[] = ${JSON.stringify(heroIds)};\n`
);

// Big file (~650 KB): only ever loaded lazily, when a 3D hero is about to be shown.
const out = resolve(root, "src/hero3d/viewerHtml.generated.ts");
writeFileSync(out, header + `export const VIEWER_HTML: string = ${JSON.stringify(html)};\n`);
console.log(`Wrote ${out} (${(html.length / 1024).toFixed(0)} KB, classic dumbbell ${(classicB64.length / 1024).toFixed(0)} KB) + heroModels.generated.ts (${heroIds.length} models)`);
